SELECT i.id, i.icon_name, i.icon_code, i.icon_type, i.icon_value, i.category_id, i.sort, i.status, i.remark, i.user_id, i.create_by, i.update_by, i.create_time, i.update_time, c.category_name FROM shop_icon i LEFT JOIN shop_category c ON c.id = i.category_id AND c.is_deleted = 0
i.is_deleted = 0
AND i.category_id = #{q.categoryId}
AND i.icon_type = #{q.iconType}
AND i.status = #{q.status}
AND (i.icon_name LIKE CONCAT('%', #{q.keyword}, '%') OR i.icon_code LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY i.status DESC, i.sort ASC, i.id DESC
